import{_ as t,a,b as o,c as i,d as s}from"./chunks/14d-tabs-context-menu.3DeBt3Hb.js";import{_ as r,o as n,c as l,a2 as h}from"./chunks/framework.DUZafPzB.js";const v=JSON.parse('{"title":"Multi-tab preview","description":"","frontmatter":{},"headers":[],"relativePath":"features/tabs.md","filePath":"features/tabs.md","lastUpdated":1791422495000}'),d={name:"features/tabs.md"};function c(b,e,p,g,u,w){return n(),l("div",null,[...e[0]||(e[0]=[h('<h1 id="multi-tab-preview" tabindex="-1">Multi-tab preview <a class="header-anchor" href="#multi-tab-preview" aria-label="Permalink to &quot;Multi-tab preview&quot;">​</a></h1><p>On desktop the preview area is a <strong>multi-tab workspace</strong>: keep a PDF report, figures, code, tables, Markdown, and Office documents open side by side, then switch, pin, and close them like browser tabs — no more bouncing back to the file list.</p><p><img src="'+t+'" alt="Multi-tab preview: six tabs, active PDF report (correlation heatmap + QC table)"></p><h2 id="opening-tabs" tabindex="-1">Opening tabs <a class="header-anchor" href="#opening-tabs" aria-label="Permalink to &quot;Opening tabs&quot;">​</a></h2><ul><li>Click a file in <strong>Files</strong>, <strong>Explorer</strong>, or <strong>Collections</strong> to open it as a tab in the preview pane. Clicking another file <strong>appends</strong> a new tab and switches to it.</li><li>A file (same Agent + root + path) <strong>never gets two tabs</strong>: clicking it again just re-activates its tab and does <strong>not</strong> reset where you were reading.</li><li><strong>Open in preview pane</strong> on a <a href="/filebox/features/search">workspace search</a> hit also opens a tab; if the file already has one, it is re-fetched so you never look at stale content.</li><li>With <strong>one</strong> tab there is no tab bar (it looks exactly like a single preview); the bar appears from the second tab on.</li><li>All three views share the same tabs: tabs opened in Files are still there in Explorer / Collections.</li></ul><h2 id="switching-tabs" tabindex="-1">Switching tabs <a class="header-anchor" href="#switching-tabs" aria-label="Permalink to &quot;Switching tabs&quot;">​</a></h2><p><img src="'+a+'" alt="Switched to the code tab qc_pipeline.py (Monaco, read-only)"></p><ul><li><strong>Click a tab</strong> to switch; the active tab has a thin accent line on top. Tabs show the file name; hover for the full <code>root/path</code>.</li><li>When tabs overflow, the strip scrolls horizontally and the active tab is always scrolled into view.</li><li>The <strong>count + ⌄</strong> button at the right end of the strip (e.g. <code>6 ⌄</code>) opens the <strong>Open previews</strong> list with every open file name and full path — click to jump. Keyboard: <code>↑</code> / <code>↓</code> to move, <code>Home</code> / <code>End</code> for first / last, <code>Enter</code> to open, <code>Esc</code> to close.</li></ul><p><img src="'+o+'" alt="Open previews jump list"></p><p><img src="'+i+'" alt="Switched to the image tab growth-kinetics.png (pinned)"></p><h2 id="pinning-tabs" tabindex="-1">Pinning tabs <a class="header-anchor" href="#pinning-tabs" aria-label="Permalink to &quot;Pinning tabs&quot;">​</a></h2><p>Each tab has a <strong>pin</strong> button next to its name:</p><table tabindex="0"><thead><tr><th>State</th><th>When you switch away and back</th></tr></thead><tbody><tr><td>Unpinned (default)</td><td>The preview reloads: PDFs return to page 1, zoom and scroll reset. Background tabs cost nothing.</td></tr><tr><td>Pinned (pin turns solid accent)</td><td>The preview stays <strong>mounted in the background</strong> — switching back is instant and keeps PDF page / zoom, image zoom, code scroll position, etc.</td></tr></tbody></table><ul><li>Or right-click a tab → <strong>Pin tab / Unpin tab</strong>.</li><li>Pinning is per tab; every pinned tab keeps using memory (HTML previews especially), so pin only what you compare repeatedly.</li><li>Pinned tabs show a small pin in the Open previews list.</li></ul><h2 id="closing-tabs" tabindex="-1">Closing tabs <a class="header-anchor" href="#closing-tabs" aria-label="Permalink to &quot;Closing tabs&quot;">​</a></h2><p><img src="'+s+'" alt="Right-click tab menu"></p><ul><li><strong>×</strong> on a tab closes that tab.</li><li><strong>×</strong> at the right of the preview header (tooltip <em>Close (Esc)</em>) closes the active tab.</li><li><strong>Right-click a tab</strong> for: <ul><li><strong>Pin tab / Unpin tab</strong></li><li><strong>Close tab</strong></li><li><strong>Close tabs to the left</strong> (disabled on the first tab)</li><li><strong>Close tabs to the right</strong> (disabled on the last tab)</li><li><strong>Close all tabs</strong></li></ul></li><li>Closing the active tab activates its <strong>neighbour</strong> (the right one first, like browsers).</li></ul><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h2><p>Active in Files / Explorer / Collections when focus is not in a text field:</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Esc</code></td><td>Close the active tab (closes the Search window first if open; with the tab menu / jump list open it only closes that)</td></tr><tr><td><code>←</code> / <code>→</code></td><td><strong>Files view only</strong>: show the previous / next file of the same folder in the current tab (the list must be showing that folder). If the target already has a tab it is activated — your other tabs are never removed</td></tr><tr><td><code>↑</code> <code>↓</code> <code>Home</code> <code>End</code> <code>Enter</code> <code>Esc</code></td><td>Navigate the Open previews jump list</td></tr></tbody></table><h2 id="preview-width" tabindex="-1">Preview width <a class="header-anchor" href="#preview-width" aria-label="Permalink to &quot;Preview width&quot;">​</a></h2><p>Drag the divider between the file list and the preview pane (list 20 %–80 %); the ratio is stored in your browser. Widen the preview when you keep many tabs so more of the strip is visible.</p><h2 id="how-tabs-behave" tabindex="-1">How tabs behave <a class="header-anchor" href="#how-tabs-behave" aria-label="Permalink to &quot;How tabs behave&quot;">​</a></h2><ul><li>The multi-tab workspace is the desktop layout (window ≥ 768 px wide); phones / narrow windows use the single-file &quot;list ↔ full-screen preview&quot; layout.</li><li>Tabs belong to the current page session; reloading or reopening the page starts with a clean workspace.</li><li><strong>Switching Agent</strong> closes all tabs (previews never outlive their machine); disabling / removing a root in Settings closes that root&#39;s tabs.</li><li>There is no tab cap; unpinned background tabs hold no viewer resources, pinned ones stay resident.</li><li>The header&#39;s <em>Refresh preview</em> button re-reads the active tab&#39;s file; <strong>Download</strong> and copy-full-server-address act on the active tab.</li><li>Tabs are ordered by when you opened them.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/filebox/features/preview">Preview (image / PDF / code / tables)</a></li><li><a href="/filebox/features/browse">Browse files</a> · <a href="/filebox/features/explorer">Explorer</a> · <a href="/filebox/features/collections">Collections</a></li></ul>',26)])])}const k=r(d,[["render",c]]);export{v as __pageData,k as default};
